  "landing.faq.title": "সচরাচর জিজ্ঞাসিত প্রশ্ন",
  "landing.faq.q1": "Second Brain কি শুধু একটি চ্যাটবট?",
  "landing.faq.a1": "না। এটি ব্যক্তিগত শেখার পরিবেশ: আপনার বিষয়বস্তু বোঝে, শেখায় এবং সময়ের সঙ্গে অগ্রগতি মনে রাখে।",
  "landing.faq.q2": "আমি কি একাধিক PDF ও নথি নিয়ে কাজ করতে পারি?",
  "landing.faq.a2": "হ্যাঁ। PDF, ছবি, স্ক্যান ও নোট পুরো একটি বিষয়ে একত্র করে শুধু একটি ফাইল নয়, সম্পূর্ণ সেট থেকে শিখতে পারেন।",
  "landing.faq.q3": "AI অধ্যাপকের সঙ্গে কী করতে পারি?",
  "landing.faq.a3": "আপনার স্তর অনুযায়ী শেখা, ব্যাখ্যা চাওয়া, আলোচনা, নির্দেশিত সেশন ও অনুশীলনী করতে পারেন।",
  "landing.faq.q4": "আমি কি AI অধ্যাপকের সঙ্গে জোরে কথা বলতে পারি?",
  "landing.faq.a4": "হ্যাঁ। কথ্য আলাপ, মৌখিক অনুশীলনী ও মৌখিক পরীক্ষা আপনাকে জোরে অনুশীলন করতে দেয়।",
  "landing.faq.q5": "ডিজিটাল টুইন কী?",
  "landing.faq.a5": "আপনার শেখার ব্যক্তিগত স্মৃতি—আপনি কী বোঝেন, আয়ত্ত করেন, ভুলে যান ও অর্জন করতে চান।",
  "landing.faq.q6": "স্মৃতি ও পুনরালোচনা কীভাবে কাজ করে?",
  "landing.faq.a6": "ব্যবধানভিত্তিক পুনরাবৃত্তি ইঞ্জিন (FSRS) সঠিক সময়ে পুনরালোচনা নির্ধারণ করে, যাতে কম চেষ্টায় বেশি মনে থাকে।",
  "landing.faq.q7": "শিক্ষাবিষয়ক কাজে কি Second Brain ব্যবহার করতে পারি?",
  "landing.faq.a7": "হ্যাঁ। শিক্ষাবিষয়ক কর্মক্ষেত্র ল্যাব, বাড়ির কাজ, প্রতিবেদন ও আরও অনেক ক্ষেত্রে পথ দেখায়—শুধু উত্তর নয়, পদ্ধতি শেখায়।",
  "landing.faq.q8": "ভাষা শেখা কীভাবে কাজ করে?",
  "landing.faq.a8": "নিমজ্জন, কথোপকথন, মৌখিক অনুশীলন ও অনুকরণে বলা—এবং নিজের পাঠ্যক্রমের ভাষা বুঝতে সহায়তা।",
  "landing.faq.q9": "আমার তথ্য কীভাবে সুরক্ষিত?",
  "landing.faq.a9": "আপনার শেখার তথ্য অভিজ্ঞতা চালায়। অ্যাকাউন্ট আপনার নিয়ন্ত্রণে এবং প্রোফাইল থেকে তথ্য পরিচালনা করতে পারেন।",
