  "landing12.hero.subtitle": "Second Brain-কে একটি প্রশ্ন, নথি বা লক্ষ্য দিন। এটি প্রসঙ্গ তৈরি করে, শেখায়, অনুশীলনে সাহায্য করে, গুরুত্বপূর্ণ বিষয় মজবুত করে এবং এরপর কী করবেন তা প্রস্তাব করে।",
