  "landing12.story.kicker": "এক পণ্য, এক অভিজ্ঞতা",
  "landing12.story.title": "পুরো ব্যবস্থায় জ্ঞানের যাত্রা দেখুন",
  "landing12.story.lead": "একটি উৎস সংরক্ষণেই থামে না। এই প্রদর্শন একই প্রসঙ্গকে নথি থেকে বোঝা, অনুশীলন, পুনরালোচনা ও শিক্ষাবিষয়ক তৈরির পথে অনুসরণ করে।",
  "landing12.story.documents.title": "একটি নথি ব্যবহারযোগ্য জ্ঞানে পরিণত হয়",
  "landing12.story.documents.short": "নথি",
  "landing12.story.documents.desc": "গ্রন্থাগার উৎস গ্রহণ করে। নথি বুদ্ধিমত্তা তা পড়ে, ধারণা বের করে এবং অগ্রগতি না বানিয়ে উৎসভিত্তিক প্রশ্ন প্রস্তুত করে।",
  "landing12.story.brain.title": "ধারণাগুলো সংযুক্ত জ্ঞানীয় মানচিত্রে যোগ হয়",
  "landing12.story.brain.short": "আমার মস্তিষ্ক",
  "landing12.story.brain.desc": "জ্ঞানীয় টুইন ধারণা, সম্পর্ক, শক্তি ও দুর্বলতা দৃশ্যমান করে। এই জনসাধারণের উদাহরণ শুধু ব্যাখ্যামূলক, বাস্তব শিক্ষার্থীর স্কোর নয়।",
  "landing12.story.professor.title": "অধ্যাপক একই প্রসঙ্গ থেকে শেখান",
  "landing12.story.professor.short": "AI অধ্যাপক",
  "landing12.story.professor.desc": "নথি, লক্ষ্য ধারণা ও শেখার উদ্দেশ্য সেশনজুড়ে থাকে। অভিজ্ঞতা ব্যাখ্যা, পাঠ, প্রশ্ন বা নির্দেশিত অনুশীলনে রূপ নিতে পারে।",
  "landing12.story.oral.title": "বোঝাপড়া কথ্য অনুশীলনে পরিণত হয়",
  "landing12.story.oral.short": "মৌখিক ও ভয়েস",
  "landing12.story.oral.desc": "শোনা, প্রতিলিপি ও উত্তর আলাদা, পাঠযোগ্য অবস্থা। প্রতিলিপি দৃশ্যমান থাকে; কোনো সাজসজ্জার তরঙ্গরেখা কথা মাপার ভান করে না।",
  "landing12.story.review.title": "দুর্বল ধারণা পুনরালোচনায় পরিণত হয়",
  "landing12.story.review.short": "পুনরালোচনা",
  "landing12.story.review.desc": "পুনরালোচনা ইঞ্জিন সঠিক সময়ে জ্ঞান মজবুত করে। এখানে দেখানো তারিখ স্পষ্টভাবে একটি প্রদর্শন, বাস্তব সময়সূচি নয়।",
  "landing12.story.workspace.title": "জ্ঞান একটি কাজে পরিণত হয়",
  "landing12.story.workspace.short": "কর্মক্ষেত্র",
  "landing12.story.workspace.desc": "প্রসঙ্গভিত্তিক সহায়ক শিক্ষার্থীর নিজস্ব কাজকে সমর্থন করার সময় শিক্ষাবিষয়ক কর্মক্ষেত্র পরিকল্পনা, লেখা, উৎস ও উদ্ধৃতি একসঙ্গে রাখে।",
  "landing12.story.sharedContext": "ভাগ করা প্রসঙ্গ",
  "landing12.story.traceability": "উৎস শনাক্তযোগ্যতা",
  "landing12.story.outcome": "আমি তথ্য দিই → Second Brain বোঝে → আমাকে শেখায় → অনুশীলনে সাহায্য করে → মনে রাখতে সাহায্য করে → কাজে লাগাতে সাহায্য করে।",
  "landing12.story.nba": "তারপর ড্যাশবোর্ডে ফেলে না রেখে একটি স্পষ্ট, ব্যাখ্যাযোগ্য পরবর্তী কাজ প্রস্তাব করে।",
  "landing12.story.file": "জীববিজ্ঞান কোর্স.pdf",
  "landing12.story.fileType": "প্রদর্শনী নথি · PDF",
