  "landing12.story.brain.note": "পণ্যের কাছে বাস্তব প্রমাণ থাকলেই মানচিত্র সম্পর্ক ও শেখার অবস্থা দেখায়।",
  "landing12.story.context.brain": "আমার মস্তিষ্ক",
