  "landing12.story.professor.question": "এই ধারণাটি এখনও কঠিন লাগে কেন?",
  "landing12.story.professor.answer": "চলুন ATP থেকে আবার গড়ি: আগে উদ্দেশ্য, তারপর ধাপ, তারপর নিজের ভাষায় সংক্ষিপ্ত যাচাই।",
  "landing12.story.professor.session": "অভিজ্ঞতা সেশন উৎস, উদ্দেশ্য, ইতিহাস ও পরবর্তী কাজ একসঙ্গে রাখে।",
  "landing12.story.oral.listen": "শোনা",
  "landing12.story.oral.transcript": "প্রতিলিপি",
  "landing12.story.oral.answer": "উত্তর",
  "landing12.story.oral.visibleTranscript": "দৃশ্যমান প্রতিলিপি",
  "landing12.story.oral.transcriptText": "“কোষীয় শ্বসন গ্লুকোজের শক্তিকে কোষের ব্যবহারযোগ্য ATP-তে রূপান্তর করে।”",
  "landing12.story.oral.note": "ভয়েস লিখিত অভিজ্ঞতাকে সম্পূর্ণ করে। অডিও সেবা ব্যর্থ হলেও পাঠযোগ্য বিষয়বস্তু কখনও সরায় না।",
  "landing12.story.review.cardLabel": "ধারণা পুনরালোচনা",
  "landing12.story.review.question": "উৎস না দেখে ATP-এর ভূমিকা ব্যাখ্যা করুন।",
  "landing12.story.review.tomorrow": "উদাহরণ: আগামীকাল পুনরালোচনা",
  "landing12.story.review.note": "বাস্তব অ্যাপ প্রকৃত পুনরালোচনার ইতিহাস থেকে সময় নির্ধারণ করে; এই ল্যান্ডিং কোনো সময়সূচি তৈরি করে না।",
  "landing12.story.review.fsrs": "ব্যবধানভিত্তিক পুনরাবৃত্তি",
