  "landing12.languages.registryLead": "মাতৃভাষা ও ইন্টারফেস-ভাষার নামই অর্থ বহন করে। একটি দেশের পতাকা অস্পষ্ট হলে নিরপেক্ষ প্রতীক ব্যবহার করা হয়।",
  "landing12.how.kicker": "যেভাবে কাজ করে",
  "landing12.how.title": "বুদ্ধিমত্তা গভীর হলেও যাত্রা সহজ",
  "landing12.how.lead": "আপনি একটি উদ্দেশ্য আনেন। Second Brain কারিগরি জটিলতা একটানা অভিজ্ঞতার আড়ালে রাখে।",
  "landing12.how.goal.title": "আপনার লক্ষ্য দিন",
