  "landing12.how.continue.title": "চালিয়ে যান",
  "landing12.how.continue.desc": "একটি ব্যাখ্যাযোগ্য পরবর্তী পদক্ষেপ অনুসরণ করুন।",
  "landing12.nba.kicker": "পরবর্তী সেরা পদক্ষেপ",
  "landing12.nba.title": "এখন কোন বিষয় মনোযোগ দাবি করে জানুন",
  "landing12.nba.lead": "সুপারিশ বাস্তব প্রসঙ্গ একত্র করে এবং কেন উপকারী তা ব্যাখ্যা করে। এগুলো প্রস্তাব, অদৃশ্য আদেশ নয়।",
