  "landing12.platform.status.coming-soon": "শিগগির আসছে; এখনও জনসাধারণের ডাউনলোড লিংক নেই",
  "landing12.download.kicker": "বহু-প্ল্যাটফর্ম ধারাবাহিকতা",
  "landing12.download.title": "যেখানেই শিখুন, Second Brain আপনার সঙ্গে",
  "landing12.download.lead": "আজ ওয়েব অভিজ্ঞতা দিয়ে শুরু করুন। মোবাইল ও ডেস্কটপ বিতরণ উপলব্ধ হওয়ার সঙ্গে সৎভাবে দেখানো হয়।",
  "landing12.download.continuity": "সেশন মডেল এমনভাবে তৈরি, যাতে এক ডিভাইসে শুরু করে অন্যটিতে আবার ধরতে পারেন।",
  "landing12.download.webAction": "ওয়েবে ব্যবহার করুন",
