  "landing12.privacy.kicker": "গোপনীয়তা ও নিয়ন্ত্রণ",
  "landing12.privacy.title": "আপনার তথ্য আপনার নিয়ন্ত্রণে থাকে",
  "landing12.privacy.lead": "Second Brain-এ স্মৃতি, নথি, বহনযোগ্যতা ও মুছে ফেলার অ্যাকাউন্ট-স্তরের নিয়ন্ত্রণ আছে।",
  "landing12.privacy.scope": "এগুলো পণ্য নিয়ন্ত্রণ, অতিরিক্ত কোনো আইনি বা নিরাপত্তার প্রতিশ্রুতি নয়।",
  "landing12.privacy.memory": "AI স্মৃতি পরিচালনা করুন",
  "landing12.privacy.export": "আপনার তথ্য রপ্তানি করুন",
